function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50) return 'nums needs 1 to 50 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value of nums is between 1 and 1000.';
  if (new Set(nums).size !== nums.length) return 'The values of nums must be distinct.';
  if (!Number.isInteger(k) || k < 1 || k > 1000) return 'k is between 1 and 1000.';
  return null;
}

