function countTheNumOfKFreeSubsets(nums, k) {
  nums.sort((a, b) => a - b);
  const groups = new Map();
  for (const num of nums) {
    const key = num % k;
    if (!groups.has(key)) {
      groups.set(key, []);
    }
    groups.get(key).push(num);
  }

  let answer = 1;
  for (const group of groups.values()) {
    let take = 0;
    let skip = 1;
    for (let i = 0; i < group.length; i++) {
      const total = take + skip;
      if (i > 0 && group[i] - group[i - 1] === k) {
        take = skip;
      } else {
        take = total;
      }
      skip = total;
    }
    answer *= take + skip;
  }
  return answer;
}

