function countTheNumOfKFreeSubsets(nums, k) {
  // Look at every subset and test every pair inside it.
  const n = nums.length;
  let count = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    let free = true;
    for (let i = 0; i < n && free; i++) {
      if (!(mask & (1 << i))) continue;
      for (let j = i + 1; j < n; j++) {
        if ((mask & (1 << j)) && Math.abs(nums[i] - nums[j]) === k) {
          free = false;
          break;
        }
      }
    }
    if (free) count++;
  }
  return count;
}

