function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const shuffle = (values) => {
    for (let i = values.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [values[i], values[j]] = [values[j], values[i]];
    }
    return values;
  };
  const range = (lo, hi) => Array.from({ length: hi - lo + 1 }, (_, i) => lo + i);
  if (size === 'small') {
    const n = int(1, 12);
    const mode = int(0, 2);
    if (mode === 0) {
      // A few residue classes with consecutive multiples of k make long conflict chains.
      const k = int(1, 6);
      const pool = [];
      for (let r = 1; r <= int(1, 3); r++) for (let j = 0; j < 8; j++) pool.push(r + j * k);
      const unique = [...new Set(pool)];
      return [shuffle(unique).slice(0, Math.min(n, unique.length)), k];
    }
    const top = mode === 1 ? Math.max(n, 20) : 1000;
    const k = mode === 1 ? int(1, 5) : int(1, 1000);
    return [shuffle(range(1, top)).slice(0, n), k];
  }
  const mode = int(0, 2);
  if (mode === 0) {
    // Spread-out values and any k: few conflicts, so the count is close to 2^50.
    return [shuffle(range(1, 1000)).slice(0, 50), int(1, 1000)];
  }
  if (mode === 1) {
    // A narrow window and a small k: many overlapping chains.
    const base = int(1, 850);
    return [shuffle(range(base, base + 150)).slice(0, 50), int(1, 4)];
  }
  // Three residue classes, each a run of multiples of k with some gaps.
  const k = int(5, 25);
  const pool = [];
  for (let r = 1; r <= 3; r++) for (let j = 0; j < 30; j++) pool.push(r + j * k);
  return [shuffle(pool).slice(0, 50), k];
}
